<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import PayrollBands,{type Band} from './PayrollBands.svelte';
	import { uiText as t } from './i18n';
	let { onupdated, editable=false }: { editable?:boolean;onupdated:(version:number,categories:string[])=>void }=$props();
	type Rule={label:string;kind:string;rate_bps:number;fixed_amount:number;basis_cap:number|null;method:string;basis:string;category:string|null;taxable:boolean;bands:Band[]};
	let rules=$state<Rule[]>([]),version=$state<number|null>(null),busy=$state(false),error=$state('');
	async function load(){try{const policy=await request<{rules:Rule[];version:number|null}>('/v1/admin/payroll-policy');rules=policy.rules.map(rule=>({...rule,method:rule.method??'flat',basis:rule.basis??'base_salary',category:rule.category??null,taxable:rule.taxable??true,bands:rule.bands??[]}));version=policy.version;if(version)onupdated(version,[...new Set(rules.flatMap(rule=>rule.category?[rule.category]:[]))]);}catch(cause){error=cause instanceof Error?cause.message:t('Data tidak dapat dimuat.');}}
	async function save(){busy=true;error='';try{await request('/v1/admin/payroll-policy',{method:'POST',body:JSON.stringify({version,rules})});await load();}catch(cause){error=cause instanceof Error?cause.message:t('Gagal menyimpan data.');}finally{busy=false;}}
	onMount(load);
</script>
<details class="panel policy"><summary>{t('Aturan kalkulasi payroll')}{#if version} · v{version}{/if}</summary>
	<p>{t('Pilih dasar dan metode perhitungan setiap aturan. Tarif BPJS dan pajak harus disetujui perusahaan sebelum digunakan.')}</p>
	{#if error}<p role="alert">{error}</p>{/if}
	<form onsubmit={event=>{event.preventDefault();if(editable)void save();}}><fieldset class="policy-body" disabled={!editable||busy}>
		{#each rules as rule,index}<fieldset><legend>{index+1}</legend><label>{t('Nama aturan')}<input bind:value={rule.label} maxlength="100" required/></label><label>{t('Jenis')}<select bind:value={rule.kind} onchange={()=>{if(rule.kind==='earning')rule.basis='base_salary';}}><option value="earning">{t('Penghasilan')}</option><option value="deduction">{t('Potongan')}</option><option value="employer">{t('Biaya perusahaan')}</option></select></label><label>{t('Metode')}<select bind:value={rule.method} onchange={()=>rule.bands=rule.method==='flat'?[]:[{up_to:null,rate_bps:rule.rate_bps}]}><option value="flat">{t('Tarif tetap')}</option><option value="tier">{t('Tarif efektif per lapisan')}</option><option value="progressive">{t('Progresif marginal')}</option></select></label><label>{t('Dasar perhitungan')}<select bind:value={rule.basis}><option value="base_salary">{t('Gaji pokok')}</option>{#if rule.kind!=='earning'}<option value="gross">{t('Gaji kotor')}</option><option value="taxable">{t('Penghasilan kena pajak')}</option>{/if}</select></label><label>{t('Kategori pajak (opsional)')}<input value={rule.category??''} oninput={event=>rule.category=event.currentTarget.value||null} maxlength="20"/></label>{#if rule.kind==='earning'}<label><input type="checkbox" bind:checked={rule.taxable}/>{t('Termasuk penghasilan kena pajak')}</label>{/if}{#if rule.method!=='flat'}<PayrollBands bind:bands={rule.bands}/>{/if}{#if rule.method==='flat'}<label>{t('Tarif (basis poin)')}<input type="number" bind:value={rule.rate_bps} min="0" max="10000" step="1" required/></label>{/if}<label>{t('Nominal tetap (Rp)')}<input type="number" bind:value={rule.fixed_amount} min="0" max="999999999" step="1" required/></label><label>{t('Batas dasar (Rp, opsional)')}<input type="number" value={rule.basis_cap??''} oninput={event=>rule.basis_cap=event.currentTarget.value?Number(event.currentTarget.value):null} min="1" max="999999999999" step="1"/></label><button type="button" class="quiet" onclick={()=>rules=rules.filter((_,i)=>i!==index)}>{t('Hapus')}</button></fieldset>{/each}
		<div class="actions"><button type="button" class="quiet" disabled={rules.length>=30} onclick={()=>rules=[...rules,{label:'',kind:'deduction',rate_bps:0,fixed_amount:0,basis_cap:null,method:'flat',basis:'base_salary',category:null,taxable:true,bands:[]}]}>{t('Tambah aturan')}</button><button disabled={busy}>{t('Simpan aturan')}</button></div>
	</fieldset></form>
</details>
<style>.policy-body{display:block;padding:0;border:0}.policy{padding:16px;border-radius:var(--radius)}summary{font-size:13px;font-weight:700;cursor:pointer}p{font-size:12px;color:var(--muted)}fieldset{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;min-width:0;border:0;border-bottom:1px solid var(--line);padding:12px 0}.actions{display:flex;gap:8px;margin-top:12px}</style>
